// ... existing imports ...

export function isBondLocked(bond: Bond, cap: number = 5): boolean {
  return bond.BondLevel >= cap && bond.BondTrack >= cap;
}

export function applySpendBond(bond: Bond, delta: number = 1, cap: number = 5): Bond {
  if (isBondLocked(bond, cap)) {
    throw new BondHandshakeError(`Cannot spend Bond on locked bond (Level ${bond.BondLevel}, Track ${bond.BondTrack}, cap ${cap})`);
  }

  const nextTrack = bond.BondTrack + delta;
  if (nextTrack < 0) {
    return {
      ...bond,
      BondLevel: bond.BondLevel - 1,
      BondTrack: cap - 1,
    };
  }
  return { ...bond, BondTrack: Math.max(0, nextTrack) };
}

export function resolveAcceptedBond(bond: Bond, cap: number = 5): Bond {
  if (!bond.proposal) return bond;

  switch (bond.proposal.type) {
    case 'SpendBond': {
      const amount = (bond.proposal as SpendBondProposal).amount ?? 1;
      return applySpendBond(bond, -amount, cap);
    }
    case 'MarkBond': {
      return {
        ...bond,
        BondTrack: Math.min(bond.BondTrack + 1, cap),
        proposal: undefined,
      };
    }
    case 'ForgeBond': {
      return {
        ...bond,
        BondLevel: Math.min(bond.BondLevel + 1, cap),
        BondTrack: 0,
        proposal: undefined,
      };
    }
    default:
      return { ...bond, proposal: undefined };
  }
}
// ... rest of file ...
