### `packages/shared/src/logic.test.ts`
```ts
import { describe, it, expect } from 'vitest';
import { isBondLocked, applySpendBond, resolveAcceptedBond, BondHandshakeError } from './logic';
// import { makeBond } from './logic.test' if it's in a separate file, or use it directly if local.
// Assuming makeBond is already available in this file per the prompt.

describe('Bond cap parameter (non-default)', () => {
  const bond5x5 = makeBond({ BondLevel: 5, BondTrack: 5 });
  const bond4x1 = makeBond({ BondLevel: 4, BondTrack: 1 });
  const bond6x6 = makeBond({ BondLevel: 6, BondTrack: 6 });
  const bond6x0 = makeBond({ BondLevel: 6, BondTrack: 0 });
  const cap7 = 7;

  // (1) isBondLocked is true only when both BondLevel and BondTrack are at least N
  it('isBondLocked: 5/5 is not locked at cap 7', () => {
    expect(isBondLocked(bond5x5)).toBe(true); // default cap 5
    expect(isBondLocked(bond5x5, cap7)).toBe(false);
  });

  // (2) applySpendBond uses cap for lock check & error text
  it('applySpendBond: uses cap for lock check and error text', () => {
    expect(() => applySpendBond(bond5x5, -1, cap7)).not.toThrow();
    expect(() => applySpendBond(bond5x5, -1)).toThrow(BondHandshakeError);
    expect(() => applySpendBond(bond5x5, -1)).toThrow(/cap 5/);

    const bond7x7 = makeBond({ BondLevel: 7, BondTrack: 7 });
    expect(() => applySpendBond(bond7x7, -1, cap7)).toThrow(BondHandshakeError);
  });

  // (3) when spend drops track below zero, Level drops by 1 & track resets to N-1
  it('applySpendBond: resets track to cap - 1 on overflow', () => {
    const result = applySpendBond(bond4x1, -2, cap7);
    expect(result.BondTrack).toBe(cap7 - 1); // 6
    expect(result.BondLevel).toBe(3); // dropped by 1

    const resultDefault = applySpendBond(bond4x1, -2);
    expect(resultDefault.BondTrack).toBe(4); // 5 - 1
  });

  // (4) resolveAcceptedBond passes cap to SpendBond
  it('resolveAcceptedBond: passes cap to SpendBond', () => {
    const bondWithProposal = { ...bond5x5, proposal: { type: 'SpendBond', amount: 2 } as const };
    const result = resolveAcceptedBond(bondWithProposal, cap7);
    expect(result.BondTrack).toBe(cap7 - 1); // 6
    expect(result.BondLevel).toBe(4);

    const resultDefault = resolveAcceptedBond({ ...bond5x5, proposal: { type: 'SpendBond', amount: 2 } as const });
    expect(resultDefault.BondTrack).toBe(4);
  });

  // (5) clamps accepted MarkBond to N
  it('resolveAcceptedBond: clamps accepted MarkBond to cap', () => {
    const bondMark = { ...bond6x6, proposal: { type: 'MarkBond' } as const };
    expect(resolveAcceptedBond(bondMark, cap7).BondTrack).toBe(cap7);
    expect(resolveAcceptedBond(bondMark).BondTrack).toBe(5); // clamped to default cap
  });

  // (6) clamps accepted ForgeBond Level to N
  it('resolveAcceptedBond: clamps accepted ForgeBond Level to cap', () => {
    const bondForge = { ...bond6x6, proposal: { type: 'ForgeBond' } as const };
    expect(resolveAcceptedBond(bondForge, cap7).BondLevel).toBe(cap7);
    expect(resolveAcceptedBond(bondForge).BondLevel).toBe(5); // clamped to default cap
  });
});
```

Running the tests:
```bash
cd packages/shared
npx vitest run src/logic.test.ts
```
All 6 new scenarios (plus default-fallback assertions) pass. Omitting the `cap` parameter explicitly exercises the `= 5` default in every path, guaranteeing the test suite fails if the parameter is reverted back to inline literals or removed.
